        self.assertEqual(wrap.wrap("aaa bbb ccc", 11), "aaa bbb ccc")
        self.assertEqual(wrap.wrap("aaa bbb ccc", 10), "aaa bbb\nccc")

    def test_whitespace_collapses_within_paragraph(self):
        self.assertEqual(wrap.wrap("a\n  b\t\tc", 10), "a b c")

    def test_paragraphs_separated_by_one_empty_line(self):
        self.assertEqual(wrap.wrap("one two\nthree\n\n\n   \nfour", 20),
                         "one two three\n\nfour")

    def test_no_leading_or_trailing_blank_lines(self):
        self.assertEqual(wrap.wrap("\n\n  hi there \n\n", 20), "hi there")

    def test_empty_input(self):
        self.assertEqual(wrap.wrap("", 10), "")
        self.assertEqual(wrap.wrap(" \n \n", 10), "")

    def test_long_word_on_its_own_line_unbroken(self):
        self.assertEqual(wrap.wrap("a supercalifragilistic b", 5),
                         "a\nsupercalifragilistic\nb")

    def test_long_word_at_start_and_end(self):
        self.assertEqual(wrap.wrap("abcdefgh x", 3), "abcdefgh\nx")
        self.assertEqual(wrap.wrap("x abcdefgh", 3), "x\nabcdefgh")

    def test_hyphenated_word_not_split(self):
        self.assertEqual(wrap.wrap("well-known fact", 6), "well-known\nfact")

    def test_width_one(self):
        self.assertEqual(wrap.wrap("a bb c", 1), "a\nbb\nc")

